val Security = createApplicationPlugin("Security") {
    onCall { call ->
        if (!authenticate(call)) return@onCall call.respond(HttpStatusCode.Unauthorized)
        if (!authorize(call)) call.respond(HttpStatusCode.Forbidden)
    }
}

fun Application.module() {
    install(Security)                       // applies to every route below
    routing { get("/orders/{id}") { /* business */ } }
}
